// WHY: kernel exports can synchronously reach hostile host hooks. Capture the
// mutable intrinsics used by the split scoped/detached entry protocol before
// any such hook can replace a prototype method and execute a host effect while
// the Wasm scope is still live.
const kernelEntryIntrinsicApply = Reflect.apply;
const kernelEntryIntrinsicArrayPush = Array.prototype.push;
const KernelEntryIntrinsicDataView = DataView;
const KernelEntryIntrinsicInt32Array = Int32Array;
const KernelEntryIntrinsicBigInt = BigInt;
const kernelEntryIntrinsicConsoleError = console.error;
const kernelEntryIntrinsicError = Error;
const kernelEntryIntrinsicConstruct = Reflect.construct;
const kernelEntryIntrinsicObjectCreate = Object.create;
const kernelEntryIntrinsicObjectDefineProperty = Object.defineProperty;
const kernelEntryIntrinsicObjectEntries = Object.entries;
const kernelEntryIntrinsicObjectFreeze = Object.freeze;
const kernelEntryIntrinsicObjectGetOwnPropertyDescriptor =
  Object.getOwnPropertyDescriptor;
const kernelEntryIntrinsicObjectSeal = Object.seal;
const kernelEntryIntrinsicMemoryBuffer =
  kernelEntryIntrinsicObjectGetOwnPropertyDescriptor(
    WebAssembly.Memory.prototype,
    "buffer",
  )!.get!;
const kernelEntryIntrinsicDataViewSetBigInt64 =
  KernelEntryIntrinsicDataView.prototype.setBigInt64;
const kernelEntryIntrinsicDataViewGetUint32 =
  KernelEntryIntrinsicDataView.prototype.getUint32;
const kernelEntryIntrinsicDataViewSetUint32 =
  KernelEntryIntrinsicDataView.prototype.setUint32;
const kernelEntryIntrinsicAtomics = Atomics;
const kernelEntryIntrinsicAtomicsLoad = Atomics.load;
const kernelEntryIntrinsicAtomicsStore = Atomics.store;
const kernelEntryIntrinsicAtomicsNotify = Atomics.notify;
const KERNEL_ENTRY_I32_BYTES = 4;

// WHY: callers already hold the KernelEntryGate token for the exact process
// memory they are materializing. Use the captured intrinsic getter so guest
// hooks cannot replace WebAssembly.Memory.prototype.buffer mid-entry.
function kernelEntryMemoryBuffer(
  memory: WebAssembly.Memory,
): ArrayBufferLike {
  return kernelEntryIntrinsicApply(
    kernelEntryIntrinsicMemoryBuffer,
    memory,
    [],
  ) as ArrayBufferLike;
}

function kernelEntryEffectFailure(
  message: string,
  cause: unknown,
): Error {
  const error = new kernelEntryIntrinsicError(message);
  kernelEntryIntrinsicObjectDefineProperty(error, "cause", {
    configurable: true,
    enumerable: false,
    writable: true,
    value: cause,
  });
  return error;
}

function concatChunksLocal(chunks: Uint8Array[]): Uint8Array {
  if (chunks.length === 0) return new Uint8Array(0);
  if (chunks.length === 1) return chunks[0]!;
  const total = chunks.reduce((s, c) => s + c.length, 0);
  const out = new Uint8Array(total);
  let off = 0;
  for (const c of chunks) {
    out.set(c, off);
    off += c.length;
  }
  return out;
}

/**
 * Validate the exact signed-i32 transfer result before a host uses it as a
 * memory bound or advances a retained input. Negative values remain the
 * kernel ABI's errno sentinel; a non-negative byte count may never exceed the
 * buffer length supplied to the kernel.
 */
function checkedKernelPipeTransferCount(
  operation: "kernel_pipe_read" | "kernel_pipe_write",
  returned: number,
  requested: number,
): number {
  if (
    !Number.isInteger(returned) || returned < -0x8000_0000 ||
    returned > requested
  ) {
    throw new Error(
      `${operation} returned an invalid byte count ${String(returned)} ` +
        `for a ${requested}-byte buffer`,
    );
  }
  return returned;
}

/** @internal Exact process-generation guard for async worker-entry continuations. */
export function isCurrentProcessGeneration<T extends { memory: WebAssembly.Memory }>(
  registry: ReadonlyMap<number, T>,
  pid: number,
  expected: T,
  memory: WebAssembly.Memory,
  execHandoffActive: boolean = false,
): boolean {
  return !execHandoffActive
    && registry.get(pid) === expected
    && expected.memory === memory;
}

/** Channel status values */
const CH_PENDING = CHANNEL_STATUS_PENDING;
const CH_COMPLETE = CHANNEL_STATUS_COMPLETE;

/** SIGEV_NONE crosses the host timer boundary as signal number zero. */
export function shouldDeliverPosixTimerSignal(signo: number): boolean {
  return Number.isInteger(signo) && signo > 0 && signo <= 64;
}

/**
 * Legacy fork-control span below each syscall channel.
 *
 * ABI 42 linked continuations allocate their frames through mmap; the first
 * pointer-sized word at `channelOffset - FORK_BUF_SIZE` is only the
 * authoritative anchor for that allocation. Keeping the anchor geometry here,
 * instead of asking each onFork consumer to reconstruct it, prevents a stale
 * fixed-buffer address from being mistaken for the linked continuation.
 */
const FORK_BUF_SIZE = FORK_SAVE_BUFFER_SIZE;

