/**
 * A complete, host-owned channel plan for a syscall whose first kernel pass
 * may park on EAGAIN.
 *
 * WHY: the guest mailbox and every nested pointer it names remain mutable
 * while the issuing thread sleeps. A retry must therefore stage only these
 * detached values and bytes; re-reading either the mailbox or process tables
 * would silently turn one logical syscall into a different operation.
 */
interface PlannedBlockingChannelDispatch {
  readonly syscallNr: number;
  readonly adjustedArgs: readonly ChannelScalarValue[];
  readonly plannedZeroLengthScratchArgMask: number;
  readonly plannedScratchWrites: readonly PlannedScratchWrite[];
  readonly plannedChannelScratchArgs: readonly PlannedChannelScratchArg[];
  readonly plannedChannelCapacity: number;
  readonly schedGetaffinityOutputInvalid: boolean;
  readonly retryForbiddenByCallFlags: boolean;
  /**
   * Full caller timeout before any bounded per-attempt conversion.
   * Present only for readiness syscalls whose public timeout lives outside
   * the generated pointer descriptors.
   */
  readonly readinessTimeoutMs?: number;
}

/**
 * One captured syscall, surfaced by the opt-in trace ring buffer
 * (enableSyscallTrace + drainSyscallTrace). Used by Kandelo Inspector →
 * Syscalls and any tooling that wants a live `strace`-equivalent.
 */
export interface SyscallTraceEvent {
  /** Monotonic time in milliseconds since the kernel-worker booted. */
  t: number;
  pid: number;
  /** Linux syscall number from `shared::Syscall`. */
  nr: number;
  /** Raw arg values as the wasm program saw them. 6 entries, undefined slots are 0. */
  args: [
    ChannelScalarValue,
    ChannelScalarValue,
    ChannelScalarValue,
    ChannelScalarValue,
    ChannelScalarValue,
    ChannelScalarValue,
  ];
  /** Human-readable syscall entry, including decoded pointer arguments when available. */
  decoded?: string;
}

/**
 * A snapshot of one process from the kernel's table. Mirrors the binary
 * record kernel_enum_procs writes. The generated PROCESS_SNAPSHOT_* values
 * come from crates/shared/src/lib.rs::process_snapshot_wire.
 */
export interface ProcessSnapshot {
  pid: number;
  ppid: number;
  /** Effective user/group IDs for ps-style USER display. */
  uid: number;
  gid: number;
  /** Sum of mmap-region sizes for this process, in bytes. */
  vsizeBytes: number;
  /** Current WebAssembly.Memory buffer size for this process, in bytes. */
  memoryBytes?: number;
  /** Process state code exposed through procfs-style snapshots. */
  state: "R" | "Z" | "S" | "D" | "T" | "I";
  /** Basename of argv[0], or "[kernel]" for an empty argv. */
  comm: string;
  /** Space-separated argv (we decode the kernel's null-separated bytes). */
  cmdline: string;
}

function parseProcSnapshots(mem: Uint8Array): ProcessSnapshot[] {
  const malformed = (reason: string): never => {
    throw new KernelScratchError(
      `malformed kernel process snapshot: ${reason}`,
      EIO,
    );
  };
  if (mem.byteLength < PROCESS_SNAPSHOT_RECORDS_OFFSET) {
    malformed("missing count prefix");
  }
  const dv = new DataView(mem.buffer, mem.byteOffset, mem.byteLength);
  const count = dv.getUint32(PROCESS_SNAPSHOT_COUNT_OFFSET, true);
  if (
    PROCESS_SNAPSHOT_COUNT_OFFSET + PROCESS_SNAPSHOT_COUNT_BYTES
      !== PROCESS_SNAPSHOT_RECORDS_OFFSET
    || count * PROCESS_SNAPSHOT_HEADER_BYTES
      > mem.byteLength - PROCESS_SNAPSHOT_RECORDS_OFFSET
  ) {
    malformed("record count exceeds the returned byte range");
  }
  let off = PROCESS_SNAPSHOT_RECORDS_OFFSET;
  const out: ProcessSnapshot[] = [];
  const dec = new TextDecoder("utf-8", { fatal: false });
  for (let i = 0; i < count; i++) {
    if (PROCESS_SNAPSHOT_HEADER_BYTES > mem.byteLength - off) {
      malformed(`record ${i} has a truncated header`);
    }
    const headerOffset = off;
    const pid = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_PID_OFFSET,
      true,
    );
    const ppid = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_PPID_OFFSET,
      true,
    );
    const uid = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_UID_OFFSET,
      true,
    );
    const gid = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_GID_OFFSET,
      true,
    );
    const vsize = dv.getBigUint64(
      headerOffset + PROCESS_SNAPSHOT_VSIZE_OFFSET,
      true,
    );
    if (vsize > BigInt(Number.MAX_SAFE_INTEGER)) {
      malformed(`record ${i} has an unrepresentable virtual size`);
    }
    const vsizeBytes = Number(vsize);
    const stateCode = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_STATE_OFFSET,
      true,
    );
    const state = ((): ProcessSnapshot["state"] => {
      switch (stateCode) {
        case 0x52:
          return "R";
        case 0x5a:
          return "Z";
        case 0x53:
          return "S";
        case 0x44:
          return "D";
        case 0x54:
          return "T";
        case 0x49:
          return "I";
        default:
          return malformed(`record ${i} has an invalid process state`);
      }
    })();
    const commLen = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_COMM_LEN_OFFSET,
      true,
    );
    const cmdLen = dv.getUint32(
      headerOffset + PROCESS_SNAPSHOT_CMDLINE_LEN_OFFSET,
      true,
    );
    off += PROCESS_SNAPSHOT_HEADER_BYTES;
    if (commLen > mem.byteLength - off) {
      malformed(`record ${i} has a truncated command name`);
    }
    const comm = dec.decode(mem.subarray(off, off + commLen));
    off += commLen;
    if (cmdLen > mem.byteLength - off) {
      malformed(`record ${i} has a truncated command line`);
    }
    const cmdRaw = mem.subarray(off, off + cmdLen);
    off += cmdLen;
    // /proc/<pid>/cmdline is null-separated; convert to space-separated.
    const cmdline = dec.decode(cmdRaw).replace(/\0/g, " ").trimEnd();
    out.push({ pid, ppid, uid, gid, vsizeBytes, state, comm, cmdline: cmdline || `[${comm}]` });
  }
  if (off !== mem.byteLength) {
    malformed("trailing bytes follow the declared records");
  }
  return out;
}

/**
 * Decode just the argv and envp strings out of a SYS_SPAWN blob. The kernel
 * does the authoritative parsing (file actions, attrs); this minimal
 * decoder exists because `onSpawn` needs `string[]` for the worker-launch
 * path.
 *
 * Wire format mirrors `crates/kernel/src/spawn.rs::parse_blob` — see
 * `docs/plans/2026-05-04-non-forking-posix-spawn-design.md` Section 1.
 *
 * Throws on malformed input. Callers should treat the throw as EINVAL.
 */
function decodeSpawnBlobStrings(
  blob: Uint8Array,
  pointerWidth: 4 | 8,
): { argv: string[]; envp: string[] } {
  if (blob.byteLength < SPAWN_WIRE_HEADER_BYTES) {
    throw new Error("blob too short for header");
  }
  const view = new DataView(blob.buffer, blob.byteOffset, blob.byteLength);
  const argc = view.getUint32(SPAWN_WIRE_HEADER_ARGC_OFFSET, true);
  const envc = view.getUint32(SPAWN_WIRE_HEADER_ENVC_OFFSET, true);
  const nActions = view.getUint32(
    SPAWN_WIRE_HEADER_ACTION_COUNT_OFFSET,
    true,
  );

  // Cap counts to mirror the kernel parser's adversarial-input cap.
  if (
    argc > SPAWN_MAX_ARGV_COUNT
    || envc > SPAWN_MAX_ENVP_COUNT
    || nActions > SPAWN_MAX_ACTION_COUNT
  ) {
    throw new Error("blob count exceeds limit");
  }

  const argvOffsetsAt = SPAWN_WIRE_HEADER_BYTES;
  const envpOffsetsAt =
    argvOffsetsAt + argc * SPAWN_WIRE_STRING_OFFSET_BYTES;
  const actionsAt =
    envpOffsetsAt + envc * SPAWN_WIRE_STRING_OFFSET_BYTES;
  const stringsAt =
    actionsAt + nActions * SPAWN_WIRE_ACTION_RECORD_BYTES;

  if (stringsAt > blob.byteLength) {
    throw new Error("blob truncated before strings region");
  }
  const stringsLen = blob.byteLength - stringsAt;
  const decoder = new TextDecoder();

  // Account for every pointer before scanning or decoding any string. Then
  // measure all referenced wire spans against one incremental budget. This
  // makes the total scanning and allocation work proportional to ARG_MAX:
  // thousands of duplicate offsets into a multi-megabyte tail are rejected
  // before TextDecoder can allocate that tail once per entry.
  let representedBytes = (argc + envc + 2) * pointerWidth;
  if (
    !Number.isSafeInteger(representedBytes)
    || representedBytes > POSIX_ARG_MAX_BYTES
  ) {
    throw new KernelScratchError(
      "spawn argv/environment pointer representation exceeds ARG_MAX",
      E2BIG,
    );
  }
  const measure = (
    offsetsAt: number,
    count: number,
  ): Array<{ start: number; end: number }> => {
    const ranges = new Array<{ start: number; end: number }>(count);
    for (let i = 0; i < count; i++) {
      const off = view.getUint32(
        offsetsAt + i * SPAWN_WIRE_STRING_OFFSET_BYTES,
        true,
      );
      if (off > stringsLen) {
        throw new KernelScratchError("spawn string offset is out of bounds", EINVAL);
      }
      let end = off;
      while (end < stringsLen && blob[stringsAt + end] !== 0) end++;
      if (end === stringsLen) {
        throw new KernelScratchError(
          "spawn string is missing its terminating NUL",
          EINVAL,
        );
      }
      const length = end - off;
      if (length > PROCESS_METADATA_ENTRY_MAX_BYTES) {
        throw new KernelScratchError(
          "spawn metadata entry exceeds the process-metadata transport limit",
          E2BIG,
        );
      }
      representedBytes += length + 1;
      if (
        !Number.isSafeInteger(representedBytes)
        || representedBytes > POSIX_ARG_MAX_BYTES
      ) {
        throw new KernelScratchError(
          "spawn argv/environment representation exceeds ARG_MAX",
          E2BIG,
        );
      }
      ranges[i] = {
        start: stringsAt + off,
        end: stringsAt + end,
      };
    }
    return ranges;
  };

  const argvRanges = measure(argvOffsetsAt, argc);
  const envpRanges = measure(envpOffsetsAt, envc);
  const decode = ({ start, end }: { start: number; end: number }): string =>
    decoder.decode(blob.subarray(start, end));
  const argv = argvRanges.map(decode);
  const envp = envpRanges.map(decode);
  return { argv, envp };
}

/** Syscall number → name mapping for logging */
export const SYSCALL_NAMES: Record<number, string> = ABI_SYSCALL_NAMES;

/** Errno number → name mapping for logging */
const ERRNO_NAMES: Record<number, string> = {
  1: "EPERM", 2: "ENOENT", 3: "ESRCH", 4: "EINTR", 5: "EIO",
  6: "ENXIO", 7: "E2BIG", 8: "ENOEXEC", 9: "EBADF", 10: "ECHILD",
  11: "EAGAIN", 12: "ENOMEM", 13: "EACCES", 14: "EFAULT", 16: "EBUSY",
  17: "EEXIST", 19: "ENODEV", 20: "ENOTDIR", 21: "EISDIR", 22: "EINVAL",
  28: "ENOSPC", 29: "ESPIPE", 30: "EROFS", 36: "ENAMETOOLONG",
  38: "ENOSYS", 39: "ENOTEMPTY", 61: "ENODATA", 75: "EOVERFLOW",
  88: "ENOTSOCK", 90: "EMSGSIZE", 92: "ENOPROTOOPT", 93: "EPROTONOSUPPORT",
  95: "EOPNOTSUPP", 97: "EAFNOSUPPORT", 98: "EADDRINUSE",
  99: "EADDRNOTAVAIL", 100: "ENETDOWN", 103: "ECONNABORTED",
  104: "ECONNRESET", 106: "EISCONN", 107: "ENOTCONN",
  110: "ETIMEDOUT", 111: "ECONNREFUSED", 114: "EALREADY",
  115: "EINPROGRESS",
};

/** Info about a registered thread channel. */
interface ChannelInfo {
  pid: number;
  memory: WebAssembly.Memory;
  channelOffset: number;
  /** Int32Array view for Atomics operations */
  i32View: Int32Array;
  /** @deprecated Kept for compat — no longer used after relistenChannel simplification. */
  consecutiveSyscalls: number;
  /** True while this channel is being handled by handleSyscall or an async
   *  retry/sleep/fork/exec path. Prevents the poller from re-entering a
   *  channel that is already in flight. Only used when usePolling=true. */
  handling?: boolean;
  /** Absolute deadline for the current finite poll/select/epoll wait. */
  readinessDeadline?: number;
  /** Force the next readiness dispatch to perform a zero-time final check. */
  readinessFinalCheck?: boolean;
}

/**
 * Host-owned identity captured once from one PENDING mailbox request.
 *
 * The syscall number cannot encode whether libc entered through
 * `__syscall_cp`: public and internal callers can issue the same number. This
 * detached identity therefore travels with every host-owned park until
 * completion. Cancellation-wake authority is independent: a cancellation
 * point entered under PTHREAD_CANCEL_DISABLE must remain blocked normally.
 */
interface FrozenCancellationPointIdentity {
  readonly cancellationPoint: boolean;
  readonly cancellationWakeAllowed: boolean;
}

interface FrozenChannelRequest extends FrozenCancellationPointIdentity {
  readonly requestFlags: number;
  readonly syscallNr: number;
}

function isWakeableCancellationPoint<
  T extends FrozenCancellationPointIdentity,
>(
  identity: T | undefined,
): identity is T {
  return identity?.cancellationPoint === true
    && identity.cancellationWakeAllowed === true;
}

/** Info about a registered process. */
interface ProcessRegistration {
  pid: number;
  memory: WebAssembly.Memory;
  channels: ChannelInfo[];
  /** True only while a vfork child borrows its suspended parent's Memory. */
  borrowedAddressSpace: boolean;
  /** Pointer width: 4 for wasm32, 8 for wasm64. */
  ptrWidth: 4 | 8;
  /**
   * True when the host registered a compact/dynamic process layout with an
   * explicit address-space ceiling. Legacy high-address thread channels lower
   * max_addr as channels are added; dynamic pthread control slots must not.
   */
  explicitMaxAddr: boolean;
}

/**
 * Host metadata for a MAP_SHARED interval. File mappings retain the existing
 * fd-backed writeback path. Anonymous mappings additionally point at a
 * host-owned backing and keep a snapshot of the bytes this process last saw.
 */
interface SharedMmapMapping {
  fd: number;
  fileOffset: number;
  len: number;
  writable: boolean;
  /** Whether the original fd permits a later PROT_WRITE upgrade. */
  writeAllowed?: boolean;
  backingKind?: "anonymous" | "file";
  backingKey?: string;
  snapshot?: Uint8Array;
  seenVersion?: number;
}

interface SharedMmapFdStat {
  dev: bigint;
  ino: bigint;
  size: number;
  mode: number;
  /** Concrete host handle used by fstat, or null for kernel-owned files. */
  hostHandle: number | null;
}

interface SharedMmapBacking {
  key: string;
  handle: number;
  writable: boolean;
  /** Authoritative size from the stable handle's fstat. */
  size: number;
  sizeValid: boolean;
  pages: Map<number, Uint8Array>;
  dirtyPages: Set<number>;
  refCount: number;
  version: number;
}

type SharedMmapHostResult<T> =
  { kind: "ok"; value: T } | { kind: "error"; errno: number };

type FileSharedMmapResult =
  | { kind: "mapped" }
  | { kind: "unsupported" }
  | { kind: "error"; errno: number };

interface PreparedFileSharedMmap {
  fd: number;
  fileOffset: number;
  len: number;
  writable: boolean;
  writeAllowed: boolean;
  backing: SharedMmapBacking;
}

type FileSharedMmapPreparationResult =
  | { kind: "prepared"; context: PreparedFileSharedMmap }
  | { kind: "unsupported" }
  | { kind: "error"; errno: number };

interface AnonymousSharedMmapBacking {
  key: string;
  bytes: Uint8Array;
  refCount: number;
  version: number;
}

interface SysvShmMapping {
  segId: number;
  size: number;
  readOnly: boolean;
  snapshot: Uint8Array;
  seenVersion: number;
}

interface PreparedInheritedSharedMapping {
  readonly mapAddr: number;
  readonly source: SharedMmapMapping;
  readonly inherited: SharedMmapMapping;
  readonly backing: AnonymousSharedMmapBacking | SharedMmapBacking;
  readonly backingKind: "anonymous" | "file";
  readonly backingVersion: number;
  readonly latest: Uint8Array;
}

interface PreparedInheritedSysvMapping {
  readonly mapAddr: number;
  readonly source: SysvShmMapping;
  readonly segId: number;
  readonly size: number;
  readonly readOnly: boolean;
}

interface PreparedSharedMappingInheritance {
  readonly parentPid: number;
  readonly childPid: number;
  readonly child: ProcessRegistration;
  readonly childMemory: WebAssembly.Memory;
  readonly parentSharedMap: Map<number, SharedMmapMapping> | undefined;
  readonly parentSharedEntries:
    readonly (readonly [number, SharedMmapMapping])[];
  readonly parentSysvMap: Map<number, SysvShmMapping> | undefined;
  readonly parentSysvEntries:
    readonly (readonly [number, SysvShmMapping])[];
  readonly sharedMappings: readonly PreparedInheritedSharedMapping[];
  readonly sysvMappings: readonly PreparedInheritedSysvMapping[];
}

interface MaterializedInheritedSysvMapping
  extends PreparedInheritedSysvMapping {
  readonly latest: Uint8Array;
  readonly seenVersion: number;
}

interface MaterializedSharedMappingInheritance {
  readonly prepared: PreparedSharedMappingInheritance;
  readonly sysvMappings: readonly MaterializedInheritedSysvMapping[];
}

interface RegisterProcessOptions {
  argv?: string[];
  env?: string[];
  ptrWidth?: 4 | 8;
  /** Width of the exec caller's argv/envp pointer arrays for ARG_MAX accounting. */
  metadataPtrWidth?: 4 | 8;
  /** Exec replaces an existing image without resetting process-level stop state. */
  preserveProcessState?: boolean;
  /** Initial program break after any host-owned low control pages. */
  brkBase?: number;
  /** Lower bound for automatic mmap allocation. */
  mmapBase?: number;
  /** mmap ceiling in process address space; defaults to legacy channel cap. */
  maxAddr?: number;
  /** brk ceiling below host-owned control pages. */
  brkLimit?: number;
  /** The process is a vfork child borrowing another process's Memory. */
  borrowedAddressSpace?: boolean;
}

type RegisterProcessStdioKind = "pipe" | "terminal";

interface RegisterProcessStdio {
  stdin: RegisterProcessStdioKind;
  stdout: RegisterProcessStdioKind;
  stderr: RegisterProcessStdioKind;
}

export const CAPTURED_STDIO: RegisterProcessStdio = {
  stdin: "pipe",
  stdout: "pipe",
  stderr: "pipe",
};

export const TERMINAL_STDIO: RegisterProcessStdio = {
  stdin: "terminal",
  stdout: "terminal",
  stderr: "terminal",
};

function encodeStdioKind(kind: RegisterProcessStdioKind): number {
  switch (kind) {
    case "pipe": return 0;
    case "terminal": return 1;
  }
}

type WaitPollResult =
  | {
      kind: "event";
      childPid: number;
      waitStatus: number;
      siCode: number;
      siStatus: number;
      childUid: number;
      rusage: Uint8Array;
    }
  | { kind: "running" }
  | { kind: "error"; errno: number };

interface ProcessSiginfoLayout {
  readonly size: number;
  readonly pidOffset: number;
  readonly uidOffset: number;
  readonly statusOffset: number;
}

const PROCESS_SIGINFO_WASM32_LAYOUT: ProcessSiginfoLayout = Object.freeze({
  size: PROCESS_SIGINFO_WASM32_SIZE,
  pidOffset: PROCESS_SIGINFO_WASM32_PID_OFFSET,
  uidOffset: PROCESS_SIGINFO_WASM32_UID_OFFSET,
  statusOffset: PROCESS_SIGINFO_WASM32_VALUE_OFFSET,
});

const PROCESS_SIGINFO_WASM64_LAYOUT: ProcessSiginfoLayout = Object.freeze({
  size: PROCESS_SIGINFO_WASM64_SIZE,
  pidOffset: PROCESS_SIGINFO_WASM64_PID_OFFSET,
  uidOffset: PROCESS_SIGINFO_WASM64_UID_OFFSET,
  statusOffset: PROCESS_SIGINFO_WASM64_VALUE_OFFSET,
});

function processSiginfoLayout(pointerWidth: number): ProcessSiginfoLayout {
  if (pointerWidth === 4) return PROCESS_SIGINFO_WASM32_LAYOUT;
  if (pointerWidth === 8) return PROCESS_SIGINFO_WASM64_LAYOUT;
  throw new Error(`unsupported process pointer width ${pointerWidth}`);
}

interface WaitingForChild extends FrozenCancellationPointIdentity {
  parentPid: number;
  channel: ChannelInfo;
  origArgs: number[];
  pid: number;
  options: number;
  syscallNr: number;
}

type ChannelOutputWrite = { ptr: number; bytes: Uint8Array };

interface PreparedChannelCompletion {
  kind: "marshalled" | "raw";
  outputWrites: ChannelOutputWrite[];
  retVal: ChannelScalarValue;
  errVal: number;
  /** Output bytes/shared backing have reached guest-visible memory. */
  materialized: boolean;
  /** Normal completions relisten themselves; raw callers opt in explicitly. */
  relistenRequested: boolean;
  /**
   * Exact clone state needed only if a stopped process's deferred Worker
   * constructor fails before this parked success can be published.
   */
  deferredClone?: {
    tid: number;
    parentTidPointer?: number;
  };
}

interface ParkedChannelCompletion {
  prepared: PreparedChannelCompletion;
  /** A raw-completion caller may request this after the completion was parked. */
  relistenRequested: boolean;
}

interface OwnedKernelWakeEvent {
  wakeIdx: number;
  wakeType: number;
}

interface DeferredProcessWorkerStart {
  expectedMemory: WebAssembly.Memory;
  start: () => void;
  cancel: () => void;
  /** Return true when operation-specific rollback fully handled the failure. */
  onStartError?: (error: unknown) => boolean;
}

export type ProcessWorkerStartDisposition =
  "started" | "deferred" | "dead" | "stale";

/**
 * Context describing a fork() initiated from a non-main thread.
 *
 * - `fnPtr` / `argPtr`: the pthread_create entry point + userdata that
 *   the kernel-worker stored when the thread was registered through
 *   `attachThreadChannel`. The child Worker uses these to enter the thread
 *   function directly (skipping `_start`).
 * - `forkBufAddr`: the dynamically allocated linked-continuation address read
 *   from the caller thread's channel anchor. In the child's memory copy this
 *   allocation holds the frames and globals saved by the parent thread.
 * - `slotStart`/`slotLen`: the dynamic pthread control reservation that
 *   contains the caller's TLS, fork-save buffer, and channel. Fork children
 *   retain this one slot and discard all other parent pthread reservations.
 */
export interface ForkFromThreadContext {
  fnPtr: number;
  argPtr: number;
  forkBufAddr: number;
  slotStart: number;
  slotLen: number;
}

/**
 * The exact continuation that a fork child must replay.
 *
 * WHY: the linked-frame address is runtime state, not a child-channel layout
 * calculation. Carry it in the kernel-owned fork request so every host and
 * test harness launches the child from the same authoritative anchor.
 */
export type ForkContinuationContext =
  | {
      readonly kind: "main";
      readonly forkBufAddr: number;
    }
  | ({
      readonly kind: "thread";
    } & Readonly<ForkFromThreadContext>);

export interface ForkBorrowedReplayWorkspace {
  /** Aligned bytes needed for every active activation's mutable prefix. */
  readonly prefixBytes: number;
  /** Page-rounded reference/exception codec scratch high-water. */
  readonly scratchBytes: number;
}

export interface ForkLaunchRequest {
  readonly parentPid: number;
  readonly childPid: number;
  readonly mode: ProcessForkMode;
  readonly parentMemory: WebAssembly.Memory;
  readonly continuation: ForkContinuationContext;
  /** Present only for vfork, measured before the kernel child is allocated. */
  readonly borrowedReplay?: ForkBorrowedReplayWorkspace;
}

export interface ResolvedSpawnProgram {
  programBytes: ArrayBuffer;
  programModule: WebAssembly.Module;
  argv: string[];
}

export interface SpawnResolveError {
  errno: number;
}

const threadChannelAttachmentBrand: unique symbol = Symbol(
  "ThreadChannelAttachment",
);

/**
 * One clone allocation event that may attach exactly one host syscall channel.
 *
 * The Rust kernel chose `tid`. Host launch code may read these immutable values
 * to initialize the thread Worker, but it cannot supply or replace the task
 * identity when attaching the channel. Object identity is validated at runtime;
 * copying these fields does not create another attachment authority.
 */
export interface ThreadChannelAttachment {
  readonly [threadChannelAttachmentBrand]: true;
  readonly pid: number;
  readonly tid: number;
  readonly fnPtr: number;
  readonly argPtr: number;
  readonly stackPtr: number;
  readonly tlsPtr: number;
  readonly ctidPtr: number;
  readonly memory: WebAssembly.Memory;
}

interface PendingThreadChannelAttachment {
  readonly owner: CentralizedKernelWorker;
  readonly pid: number;
  readonly tid: number;
  readonly fnPtr: number;
  readonly argPtr: number;
  readonly memory: WebAssembly.Memory;
  attachedChannelOffset?: number;
}

interface CloneRollbackState {
  parentTidWritten: boolean;
  cloneAttachment?: ThreadChannelAttachment;
  pendingAttachment?: PendingThreadChannelAttachment;
}

// Module-private authority store: neither a caller nor a subclass can mint a
// capability or install a forged WeakMap record through the public object.
const pendingThreadChannelAttachments =
  new WeakMap<ThreadChannelAttachment, PendingThreadChannelAttachment>();

function createThreadChannelAttachment(
  owner: CentralizedKernelWorker,
  pid: number,
  tid: number,
  fnPtr: number,
  argPtr: number,
  stackPtr: number,
  tlsPtr: number,
  ctidPtr: number,
  memory: WebAssembly.Memory,
): {
  attachment: ThreadChannelAttachment;
  pending: PendingThreadChannelAttachment;
} {
  const attachment = Object.freeze({
    [threadChannelAttachmentBrand]: true as const,
    pid,
    tid,
    fnPtr,
    argPtr,
    stackPtr,
    tlsPtr,
    ctidPtr,
    memory,
  }) as ThreadChannelAttachment;
  const pending: PendingThreadChannelAttachment = {
    owner,
    pid,
    tid,
    fnPtr,
    argPtr,
    memory,
  };
  pendingThreadChannelAttachments.set(attachment, pending);
  return { attachment, pending };
}

export type SpawnProgramResolution = ResolvedSpawnProgram | SpawnResolveError;

interface ReservedSpawnScratch {
  // A token exists before its pointer/capacity can be validated. Keeping that
  // token in the value even when region construction fails guarantees the
  // caller still reaches the one cleanup path.
  region: KernelScratchRegion | null;
  token: bigint;
}

interface ReservedTransferScratch {
  // A token exists before its pointer/capacity can be validated. Retain it so
  // every non-trapping path can settle the Rust reservation exactly once.
  region: KernelScratchRegion | null;
  token: bigint;
}

interface FlattenedTransferRequest {
  fd: number;
  entries: readonly CheckedProcessIovec[];
  totalData: number;
  read: boolean;
  offset: bigint | null;
  /**
   * Complete detached write payload. Required for retryable writes so later
   * attempts never consult mutable process buffers again.
   */
  inputBytes?: Uint8Array;
}

interface BlockingRetryDisposition extends FrozenCancellationPointIdentity {
  /** Request-local flags such as MSG_DONTWAIT forbid a host-owned park. */
  readonly retryForbiddenByCallFlags: boolean;
  /** Exact first-attempt descriptor policy; never re-resolve after fd reuse. */
  readonly fdWasNonblocking: boolean;
  /** Exact first-attempt socket timeout, captured only for a blocking retry. */
  readonly applicableSocketTimeoutMs: number;
}

interface GenericBlockingRetrySnapshot extends BlockingRetryDisposition {
  readonly kind: "generic-channel";
  readonly syscallNr: number;
  readonly origArgs: number[];
  readonly argDescs: SyscallArgDesc[] | undefined;
  readonly dispatch: PlannedBlockingChannelDispatch;
  readonly retryToken: bigint;
}

interface FcntlLockBlockingRetrySnapshot
  extends FrozenCancellationPointIdentity {
  readonly kind: "fcntl-lock";
  readonly syscallNr: typeof SYS_FCNTL;
  readonly origArgs: number[];
  readonly flockPointer: number;
  readonly flockBytes: Uint8Array;
  readonly retryToken: bigint;
}

interface SelectBlockingRetrySnapshot
  extends FrozenCancellationPointIdentity {
  readonly kind: "select";
  readonly syscallNr: typeof SYS_SELECT | typeof SYS_PSELECT6;
  readonly origArgs: number[];
  readonly nfds: number;
  readonly readPointer: number;
  readonly writePointer: number;
  readonly exceptPointer: number;
  readonly readBytes: Uint8Array | null;
  readonly writeBytes: Uint8Array | null;
  readonly exceptBytes: Uint8Array | null;
  readonly timeoutMs: number;
  readonly maskBytes: Uint8Array | null;
  readonly retryToken: bigint;
}

interface FlattenedBlockingRetrySnapshot extends BlockingRetryDisposition {
  readonly kind: "flattened-transfer";
  readonly syscallNr: number;
  readonly origArgs: number[];
  readonly request: FlattenedTransferRequest;
  readonly retryToken: bigint;
}

interface SendmsgBlockingRetrySnapshot extends BlockingRetryDisposition {
  readonly kind: "sendmsg";
  readonly syscallNr: typeof SYS_SENDMSG;
  readonly origArgs: number[];
  readonly message: CheckedProcessMessage;
  readonly layout: KernelMessageLayout;
  readonly totalCapacity: number;
  readonly name: Uint8Array;
  readonly control: Uint8Array;
  readonly payload: Uint8Array;
  readonly retryToken: bigint;
}

interface RecvmsgBlockingRetrySnapshot extends BlockingRetryDisposition {
  readonly kind: "recvmsg";
  readonly syscallNr: typeof SYS_RECVMSG;
  readonly origArgs: number[];
  readonly message: CheckedProcessMessage;
  readonly layout: KernelMessageLayout;
  readonly totalCapacity: number;
  readonly retryToken: bigint;
}

interface SysvMessageBlockingRetrySnapshot
  extends FrozenCancellationPointIdentity {
  readonly kind: "sysv-message";
  readonly syscallNr: typeof SYS_MSGSND | typeof SYS_MSGRCV;
  readonly origArgs: number[];
  readonly pointerWidth: 4 | 8;
  readonly processPointer: number;
  readonly messageSize: number;
  readonly flags: number;
  readonly input: Uint8Array | null;
  readonly nativeType: bigint;
  readonly messageType: bigint;
  readonly retryToken: bigint;
}

type BlockingRetrySnapshot =
  | GenericBlockingRetrySnapshot
  | FcntlLockBlockingRetrySnapshot
  | SelectBlockingRetrySnapshot
  | FlattenedBlockingRetrySnapshot
  | SendmsgBlockingRetrySnapshot
  | RecvmsgBlockingRetrySnapshot
  | SysvMessageBlockingRetrySnapshot;

interface BlockingRetryWakeTargets {
  readonly readPipeIndex?: number;
  readonly writePipeIndex?: number;
  readonly acceptIndex?: number;
  readonly pollPipeIndices?: readonly number[];
  readonly pollAcceptIndices?: readonly number[];
}

function isSpawnResolveError(
  resolution: SpawnProgramResolution,
): resolution is SpawnResolveError {
  return "errno" in resolution &&
    typeof resolution.errno === "number";
}

/** Callbacks for fork/exec/exit handling. */
export interface CentralizedKernelCallbacks {
  /**
   * Observe an object in the persistent kernel realm that can retain one
   * process-memory generation. The allocator uses this only for bounded weak
   * retirement telemetry; explicit generation teardown remains authoritative.
   */
  onProcessMemoryTarget?: (
    memory: WebAssembly.Memory,
    target: object,
  ) => void;
  /**
   * Called exactly once when the kernel instance can no longer be used
   * safely by any process.
   *
   * The entry layer must terminate the dedicated kernel Worker. A transfer
   * import trap can strand a Rust-owned global reservation in Executing state,
   * so neither completing one guest with EIO nor continuing to dispatch other
   * channels is a valid recovery boundary.
   */
  onKernelFatal?: (error: Error) => void;

  /**
   * Called when a process forks. The kernel has already cloned the Process
   * in its ProcessTable. The callback should spawn a child Worker with
   * a copy of the parent's Memory and register it with the kernel.
   * Returns the channel offsets allocated for the child.
   *
   * `request.continuation.kind` is `"thread"` when the parent issued the
   * fork() syscall from a pthread-created thread (i.e. on a channel registered
   * through a host-side `ThreadChannelAttachment` bound to the kernel's exact
   * clone result, with tid > 0).
   * The host must:
   *   - use the thread's `forkBufAddr` (not the main channel's) for the
   *     child's rewind so the saved frames + saved __tls_base /
   *     __stack_pointer match what the parent thread populated, and
   *   - have the child Worker enter the thread function (`fnPtr`/`argPtr`)
   *     directly instead of `_start` — _start is not in the thread's
   *     fork-path call chain and rewinding through it would never reach
   *     the saved fork() call site.
   *
   * Main-thread and pthread forks both carry the authoritative linked
   * continuation address in `request.continuation.forkBufAddr`.
   */
  onFork?: (request: ForkLaunchRequest) => Promise<number[]>;

  /**
   * Called when a process calls execve. The callback should resolve the
   * program path, terminate the old Worker, create a new Worker with the
   * new binary, and attach its channels to the existing kernel Process.
   * Returns 0 on success, negative errno on error.
   */
  onExec?: ExecLaunchCallback;

  /**
   * Pre-flight resolution step for SYS_SPAWN. Returns the validated program
   * bytes, their compiled module, and launch argv for `path`, `{ errno }` for
   * a located but unlaunchable program, or `null` for ENOENT. **Must NOT have
   * side effects** —
   * `handleSpawn` calls this BEFORE `kernel_spawn_process` so that file
   * actions never run on a doomed PATH-iteration. POSIX requires
   * file_actions to run "exactly once," and `posix_spawnp`'s PATH-walk
   * issues one `posix_spawn` per candidate; without this preflight the
   * kernel applies file_actions on every failed iteration (sortix
   * `basic/spawn/posix_spawnp` exercises an `addopen(O_EXCL)` "once"
   * file that would conflict on iteration 2).
   *
   * Required if `onSpawn` is set; together they form the spawn surface.
   */
  onResolveSpawn?: (path: string, argv: string[]) => Promise<SpawnProgramResolution | null>;

  /**
   * Launch a worker for the spawned child with bytes and module derived from
   * its exact committed target. `onResolveSpawn` is only a side-effect-free
   * candidate; the shared worker re-resolves after attrs/file actions and
   * recompiles whenever those bytes differ. The kernel has constructed and
   * committed the child Process under `childPid` by the time this is called.
   * The callback instantiates a fresh Worker and attaches its channels to that
   * existing Process.
   *
   * Returns 0 on success, negative errno on failure. On non-zero return
   * the kernel descriptor is rolled back via `kernel_remove_process`.
   *
   * Distinct from `onExec` (which replaces the calling worker) and
   * `onFork` (which clones the parent's Memory): `onSpawn` always
   * creates a fresh Memory and runs the new program from `_start`.
  */
  onSpawn?: (
    parentPid: number,
    childPid: number,
    program: ResolvedSpawnProgram,
    envp: string[],
  ) => Promise<number>;

  /**
   * Called when a process calls clone (thread creation). The callback should
   * spawn a thread Worker sharing the parent's Memory. The Rust kernel has
   * already allocated the task identity. The host creates a one-shot transport
   * proof bound to that exact clone result; the callback may read its fields
   * for Worker initialization, then must consume it with
   * `attachThreadChannel`. It cannot supply or replace the PID/TID.
   */
  onClone?: (attachment: ThreadChannelAttachment) => Promise<void>;

  /**
   * Called after a pthread channel reaches SYS_EXIT and the kernel worker has
   * performed the musl clear-TID wake and completed the exit channel. The host
   * may now terminate the backing Worker without leaving its channel waiter
   * attached to a slot that will later be reused.
   */
  onThreadExit?: (pid: number, tid: number, channelOffset: number) => boolean;

  /**
   * Called when a process exits.
   */
  onExit?: (pid: number, exitStatus: number) => void;

  /**
   * Called when a process calls exit_group (terminate all threads).
   * The callback should forcefully terminate all thread workers for the process.
   * Called BEFORE the process exit is processed.
   */
  onExitGroup?: (pid: number) => void;
}

