/**
 * Module-private observation seams for the legacy scratch-boundary suite.
 *
 * WHY: these callbacks deliberately receive only value-level syscall state,
 * never a KernelWorkerEntryContext. Keeping them in one frozen private record
 * avoids installing mutable method shadows on the authority-bearing worker.
 */
interface ScratchBoundaryTestHooks {
  readonly fdSupportsMmapWriteback?: (
    pid: number,
    fd: number,
  ) => boolean;
  readonly getFdStatForSharedMapping?: (
    channel: Pick<ChannelInfo, "pid" | "memory" | "channelOffset">,
    fd: number,
  ) => SharedMmapHostResult<SharedMmapFdStat>;
  readonly getFdPathForSharedMapping?: (
    channel: Pick<ChannelInfo, "pid">,
    fd: number,
  ) => SharedMmapHostResult<string>;
  readonly getFdAccessModeForSharedMapping?: (
    channel: Pick<ChannelInfo, "pid" | "memory" | "channelOffset">,
    fd: number,
  ) => SharedMmapHostResult<number>;
  readonly getPtrWidth?: (pid: number) => 4 | 8;
  readonly guestTidForChannel?: (channel: ChannelInfo) => number;
  readonly afterProcessMemorySnapshot?: (channel: ChannelInfo) => void;
  readonly handleBlockingRetry?: (
    channel: ChannelInfo,
    syscallNr: number,
    origArgs: number[],
  ) => void;
  readonly deferChannelWhileStopped?: (channel: ChannelInfo) => boolean;
  readonly getReadinessDeadline?: (
    channel: ChannelInfo,
    timeoutMs: number,
  ) => number;
  readonly isRegisteredChannel?: (channel: ChannelInfo) => boolean;
  readonly handleSharedMappingsAfterFileSyscall?: (
    channel: ChannelInfo,
    syscallNr: number,
    origArgs: number[],
    retVal: number,
    errVal: number,
    positionedOffset?: bigint,
    truncateLength?: bigint,
  ) => void;
  readonly synchronizeSharedMemoryForBoundary?: (
    process: Pick<ChannelInfo, "pid" | "memory">,
  ) => void;
  readonly completeChannel?: (
    channel: ChannelInfo,
    syscallNr: number,
    origArgs: number[],
    argDescs: SyscallArgDesc[] | undefined,
    retVal: ChannelScalarValue,
    errVal: number,
    detachedOutput?: ChannelOutputWrite[],
  ) => void;
  readonly completeChannelRaw?: (
    channel: ChannelInfo,
    retVal: number,
    errVal: number,
  ) => void;
  readonly relistenChannel?: (channel: ChannelInfo) => void;
  readonly wakePendingSignalWaits?: (
    pid: number,
    signum: number,
    targetTid?: number,
  ) => void;
  readonly sendSignalToProcess?: (
    targetPid: number,
    signum: number,
    queueSignal?: boolean,
  ) => void;
  readonly scheduleWakeBlockedRetries?: () => void;
  readonly retrySyscall?: (channel: ChannelInfo) => void;
  readonly interruptWaitingChildForDirectedSignal?: (
    pid: number,
    tid: number,
  ) => boolean;
  readonly interruptWaitingChildrenForGeneratedSignal?: (
    signum: number,
  ) => void;
}

